<template>
    <divider
        v-if="item.type === 'Divider'"
        :text="item.text"
        :image="item.image"
        :base="item.base"
        :flipRight="item.flipRight"
    />
    <symbolsAndPayouts
        v-else-if="item.type === 'SymbolsAndPayouts'"
        :symbols="item.symbols"
        :color="item.color"
        :base="item.base"
    />
    <ImageAndText
        v-else-if="item.type === 'ImageAndText'"
        :text="item.text"
        :image="item.image"
        :base="item.base"
        :alignText="item.alignText"
        :imagePercentage="item.imagePercentage"
        :imageFirst="item.imageFirst"
    />
    <HorizontalImages
        v-else-if="item.type === 'HorizontalImages'"
        :images="item.images"
        :base="item.base"
        :imagePadding="item.imagePadding"
    />
    <HTPText
        v-else-if="item.type === 'Text'"
        :text="item.text"
        :base="item.base"
        :alignText="item.alignText"
    />
    <VerticalImages
        v-else-if="item.type === 'VerticalImages'"
        :images="item.images"
        :base="item.base"
    />
    <SingleImage
        v-else-if="item.type === 'SingleImage'"
        :image="item.image"
        :base="item.base"
    />
    <TextList
        v-else-if="item.type === 'TextList'"
        :text="item.text"
        :base="item.base"
        :alignText="item.alignText"
    />
    <Padding 
        :height="item.height"
        v-else-if="item.type === 'Padding'" />
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import Divider from './components/divider/divider.vue';
import SymbolsAndPayouts from './components/symbols-and-payouts/symbols-and-payouts.vue';

import ImageAndText from './components/image-and-text/image-and-text.vue';
import HorizontalImages from './components/horizontal-images/horizontal-images.vue';
import VerticalImages from './components/vertical-images/vertical-images.vue';
import SingleImage from './components/single-image/single-image.vue';
import HTPText from './components/text/text.vue';
import TextList from './components/text-list/text-list.vue';
import Padding from './components/padding/padding.vue';
import { IVueHtpComponent } from '../../types'


export default defineComponent({
  name: 'HtpItem',
  components: {
        Divider,
        SymbolsAndPayouts,
        ImageAndText,
        HorizontalImages,
        VerticalImages,
        SingleImage,
        HTPText,
        TextList,
        Padding
    },
  props: {
    item: {
      type: Object as () => IVueHtpComponent,
      required: true
    }
  },
  computed: {
    componentName(): string {
      // Map item type to component name
      const typeMap: Record<string, string> = {
        'Divider': 'divider',
        'SymbolsAndPayouts': 'symbolsAndPayouts',
        'ImageAndText': 'ImageAndText',
        'HorizontalImages': 'HorizontalImages',
        'Text': 'HTPText',
        'VerticalImages': 'VerticalImages',
        'SingleImage': 'SingleImage',
        'TextList': 'TextList',
        'Padding': 'Padding'
      };
      
      return typeMap[this.item.type] || 'div';
    }
  }
});
</script>

